// Fuzz stub for Base64::Encode overloads. No persistent inputs/outputs are required.
// We exercise all four overloads and assert cross-overload consistency.

// 1) Raw buffer -> output reference
std::string raw1 = FUZZ_PARAM_STR();
unsigned int len1 = 0;
if (!raw1.empty()) {
    // Choose a valid length within the buffer bounds to satisfy API requirement
    unsigned int rnd = *FUZZ_PARAM(unsigned int);
    len1 = (unsigned int)(rnd % (raw1.size() + 1));
}
std::string enc_ref_from_buf;
Base64::Encode(raw1.data(), len1, enc_ref_from_buf);

// 2) Raw buffer -> returned string
std::string enc_ret_from_buf = Base64::Encode(raw1.data(), len1);

// Cross-check: both buffer-based overloads must produce identical results for the same input
FUZZ_ASSERT(enc_ref_from_buf == enc_ret_from_buf, "Encode(char*,len) overloads must be consistent");

// 3) std::string input -> output reference (ensure distinct objects for input and output)
std::string raw2 = FUZZ_PARAM_STR();
std::string enc_ref_from_str;
Base64::Encode(raw2, enc_ref_from_str);

// 4) std::string input -> returned string
std::string enc_ret_from_str = Base64::Encode(raw2);

// Cross-check: both string-based overloads must produce identical results for the same input
FUZZ_ASSERT(enc_ref_from_str == enc_ret_from_str, "Encode(string) overloads must be consistent");

// Additional property: if raw2 equals the first len1 bytes of raw1, the corresponding encodings should match
// Compute a comparable slice without reallocating large memory; keep sizes bounded by FUZZ runtime.
if (raw2.size() == len1 && len1 <= raw1.size()) {
    std::string raw1_prefix(raw1.data(), raw1.data() + len1);
    // Re-encode the prefix using the string overload and compare to buffer overload result
    std::string enc_prefix = Base64::Encode(raw1_prefix);
    FUZZ_ASSERT(enc_prefix == enc_ref_from_buf, "Encode equivalence between buffer slice and string input");
}

