// Fuzz stub for Base64::Decode overloads. We generate valid Base64 by encoding random bytes first
// to satisfy the API's expectation of valid Base64 input, then exercise all four overloads.

// Create random binary and its Base64 encoding
std::string bin = FUZZ_PARAM_STR();
std::string b64_full = Base64::Encode(bin);

// 1) char* + length variants: choose a length that is a multiple of 4 and within bounds
unsigned int len_candidate = 0;
if (!b64_full.empty()) {
    unsigned int rnd = *FUZZ_PARAM(unsigned int);
    len_candidate = (unsigned int)(rnd % (b64_full.size() + 1));
}
unsigned int len4 = (len_candidate / 4) * 4; // enforce multiple-of-4 as typical for Base64 text

// Decode using output reference
std::string dec_ref_from_buf;
Base64::Decode(b64_full.c_str(), len4, dec_ref_from_buf);

// Decode using return value
std::string dec_ret_from_buf = Base64::Decode(b64_full.c_str(), len4);

// Cross-check: both buffer-based overloads must produce identical results for the same Base64 prefix
FUZZ_ASSERT(dec_ref_from_buf == dec_ret_from_buf, "Decode(char*,len) overloads must be consistent");

// If we decoded the full Base64 text, assert perfect round-trip
if (len4 == b64_full.size()) {
    FUZZ_ASSERT(dec_ref_from_buf == bin, "Decode(Full) should round-trip to original binary");
}

// 2) std::string input variants: use full, valid Base64 to avoid unspecified behavior
std::string dec_ref_from_str;
Base64::Decode(b64_full, dec_ref_from_str);
std::string dec_ret_from_str = Base64::Decode(b64_full);

// Cross-check: both string-based overloads must be identical and round-trip
FUZZ_ASSERT(dec_ref_from_str == dec_ret_from_str, "Decode(string) overloads must be consistent");
FUZZ_ASSERT(dec_ref_from_str == bin, "Decode(string full) should round-trip to original binary");

// Additional property: Re-encode the decoded bytes should reconstruct the original Base64 text
// (canonical encoding expected as implementation is deterministic)
std::string re_b64_from_str = Base64::Encode(dec_ref_from_str);
FUZZ_ASSERT(re_b64_from_str == b64_full, "Encode(Decode(x)) must equal original Base64 text");

